const update = $input.first().json.body || $input.first().json;
const cb = update.callback_query || null;
const m = update.message || cb?.message || {};
const from = cb?.from || m.from || {};
const chatId = m.chat?.id;
if (!chatId || !from.id) throw new Error('Bale event lacks chat/user ID');
return [{json:{
  chat_id:String(chatId), user_id:String(from.id),
  text:String(update.message?.text || '').trim(),
  callback:String(cb?.data || ''),
  callback_id:String(cb?.id || ''),
  message_id:String(cb?.message?.message_id || ''),
  event_id:String(update.update_id || ''),
  received_at:new Date().toISOString(),
}}];

// CONEX ID 2.0: project workflow backed by 4 Google Sheets tabs.
// Recovery admin. Verify that this is a USER ID (use /id), not only chat ID.
const BOOTSTRAP_ADMIN_USER_IDS = ['REPLACE_WITH_YOUR_BALE_USER_ID'];
const ENABLE_PUBLIC_READ = false;

const incoming = {...$('Normalize Bale Event').first().json};
const allSessions = $('Read Sessions').all().map(i=>i.json).filter(r=>r && r.User_ID);
const allProjects = $('Read Projects').all().map(i=>i.json).filter(r=>r && r.Project_ID);
const allUsers = $('Read Users').all().map(i=>i.json).filter(r=>r && r.User_ID);
const readError = ['Read Sessions','Read Users','Read Projects'].some(name =>
  $(name).all().some(item => !!item.json?.error));
const userId = String(incoming.user_id);
const chatId = String(incoming.chat_id);
const userRecord=allUsers.find(u=>String(u.User_ID)===userId);
const active = userRecord && ['true','1','yes','active'].includes(String(userRecord.Active).toLowerCase());
const isAdmin = BOOTSTRAP_ADMIN_USER_IDS.includes(userId) || !!(active && userRecord.Role==='admin');
const isAllowed = isAdmin || ENABLE_PUBLIC_READ || !!active;
const now = new Date().toISOString();

// Fixed bottom menu (reply keyboard). Tapping a button sends its label as text;
// map labels to the same actions as the glass (inline) buttons.
const FIXED = {
  '🏠 منوی اصلی':'m:main', '🔎 جستجو':'m:search', '📋 پروژه‌ها':'m:list:0',
  '📊 آمار':'m:stats', '➕ پروژه جدید':'m:add', '👥 کاربران':'m:users:0',
};
const fromFixedMenu = !incoming.callback && Object.prototype.hasOwnProperty.call(FIXED, incoming.text);
if (fromFixedMenu) { incoming.callback = FIXED[incoming.text]; incoming.text = ''; }
function fixedKeyboard() {
  const rows = [[{text:'🏠 منوی اصلی'},{text:'🔎 جستجو'}],[{text:'📋 پروژه‌ها'},{text:'📊 آمار'}]];
  if (isAdmin) rows.push([{text:'➕ پروژه جدید'},{text:'👥 کاربران'}]);
  return {keyboard:rows, resize_keyboard:true};
}

function norm(x) {
  const persian = '۰۱۲۳۴۵۶۷۸۹';
  const arabic = '٠١٢٣٤٥٦٧٨٩';
  return String(x ?? '').normalize('NFKC').replace(/[ي]/g,'ی').replace(/[ك]/g,'ک')
    .replace(/[۰-۹]/g,c=>String(persian.indexOf(c)))
    .replace(/[٠-٩]/g,c=>String(arabic.indexOf(c)))
    .toLowerCase().replace(/[\s_\-–—]+/g,'').trim();
}
function button(label, action) { return {text:label, callback_data:action}; }
function kb(rows) { return {inline_keyboard:rows}; }
function mainKeyboard() {
  const rows = [
    [button('🔎 جستجوی پروژه','m:search')],
    [button('📋 لیست پروژه‌ها','m:list:0'),button('📊 وضعیت BOM','m:bom')],
    [button('📈 آمار پروژه‌ها','m:stats')],
  ];
  if (isAdmin) {
    rows.push([button('➕ ثبت پروژه جدید','m:add'),button('🛠 مدیریت پروژه‌ها','m:manage:0')]);
    rows.push([button('👥 مدیریت کاربران','m:users:0')]);
  }
  return kb(rows);
}
function back() { return [button('🏠 منوی اصلی','m:main')]; }
function statusName(s) { return s === 'registered' ? '✅ ثبت شده' : s === 'not_registered' ? '❌ ثبت نشده' : '❔ نامشخص'; }
function projectText(p) {
  return '📁 پروژه: '+String(p.Project_Name||'—')+'\n'+
    'گروه پروژه: '+String(p.Project_Group||'—')+'\n'+
    'کد SAP: '+String(p.SAP_Code||'—')+'\n'+
    'BOM: '+statusName(p.BOM_Status)+'\n'+
    'ثبت/تغییر BOM: '+String(p.BOM_Updated_At||'—')+'\n'+
    'آخرین تغییر پروژه: '+String(p.Updated_At||'—');
}
function details(p) {
  const rows=[];
  if(isAdmin) rows.push([button('✏️ ویرایش پروژه','e:'+p.Project_ID),button('🔄 تغییر BOM','b:'+p.Project_ID)]);
  rows.push([button('🔎 جستجوی جدید','m:search')],back());
  return {text:projectText(p),keyboard:kb(rows)};
}
function paged(list,page,prefix,label) {
  const size=6, pages=Math.max(1,Math.ceil(list.length/size));
  page=Math.max(0,Math.min(pages-1,Number(page)||0));
  if(!list.length) return {text:'موردی برای نمایش وجود ندارد.',keyboard:kb([back()])};
  const rows=list.slice(page*size,page*size+size).map(p=>[button(String(p.Project_Name||p.Project_ID).slice(0,50),'p:'+p.Project_ID)]);
  const pager=[];
  if(page>0) pager.push(button('◀️ قبلی',prefix+':'+(page-1)));
  if(page<pages-1) pager.push(button('بعدی ▶️',prefix+':'+(page+1)));
  if(pager.length) rows.push(pager);
  rows.push(back());
  return {text:label+' — صفحه '+(page+1)+' از '+pages+' ('+list.length+' مورد)',keyboard:kb(rows)};
}
function findProject(id) { return allProjects.find(p=>String(p.Project_ID)===id); }
function findUser(id) { return allUsers.find(u=>String(u.User_ID)===id); }
function userDetails(u) {
  return 'کاربر: '+String(u.Display_Name||'—')+'\nشناسه بله: '+u.User_ID+'\nنقش: '+String(u.Role||'viewer')+'\nفعال: '+String(u.Active);
}
function userMenu(u) {
  return kb([
    [button('👁 مشاهده‌گر','ur:v:'+u.User_ID),button('👑 مدیر','ur:a:'+u.User_ID)],
    [button(String(u.Active).toLowerCase()==='true'?'🚫 غیرفعال‌سازی':'✅ فعال‌سازی','ut:'+u.User_ID)],
    [button('👥 فهرست کاربران','m:users:0')],back(),
  ]);
}
function userPaged(page) {
  const users=allUsers.slice().sort((a,b)=>String(a.Display_Name).localeCompare(String(b.Display_Name),'fa'));
  const size=6,pages=Math.max(1,Math.ceil(users.length/size));
  page=Math.max(0,Math.min(pages-1,Number(page)||0));
  const rows=users.slice(page*size,page*size+size).map(u=>[button(String(u.Display_Name||u.User_ID).slice(0,45),'user:'+u.User_ID)]);
  const nav=[];
  if(page>0)nav.push(button('◀️ قبلی','m:users:'+(page-1)));
  if(page<pages-1)nav.push(button('بعدی ▶️','m:users:'+(page+1)));
  if(nav.length)rows.push(nav);
  rows.push([button('➕ افزودن همکار','m:uadd')],back());
  return {text:'👥 کاربران مجاز: '+users.length+' — صفحه '+(page+1)+' از '+pages,keyboard:kb(rows)};
}

let s = allSessions.find(x=>String(x.User_ID)===userId) || {};
let step = String(s.Step||'idle');
let draft = {};
try { draft=JSON.parse(s.Draft_JSON||'{}') || {}; } catch { draft={}; }
if(s.Updated_At && Date.now()-Date.parse(s.Updated_At)>30*60*1000){step='idle';draft={};}

let text=''; let keyboard=mainKeyboard(); let mutation=null;
let userMutation=null;let audit=null;
function say(t,k=mainKeyboard()){text=t;keyboard=k;}
function reset(){step='idle';draft={};}
function ask(t){say(t,kb([[button('❌ لغو','m:main')]]));}
function auditChange(action,entity,before,after){
  audit={Event_ID:String(incoming.event_id||'callback')+'-'+action+'-'+entity,
    Action:action,Entity_ID:String(entity),User_ID:userId,Timestamp:now,
    Before_JSON:JSON.stringify(before||{}),After_JSON:JSON.stringify(after||{})};
}

// Anyone can determine their real Bale user ID without accessing factory data.
if(readError) {
  reset();say('⚠️ ارتباط با بانک اطلاعاتی پروژه‌ها برقرار نیست. لطفاً کمی بعد دوباره تلاش کنید.\nاین خطا در اجرای n8n ثبت شده است.',kb([]));
} else if(incoming.text==='/id') {
  say('شناسه کاربر بله: '+userId+'\nشناسه گفتگو: '+chatId+'\nاین شناسه را فقط برای ثبت مجوز دسترسی استفاده کنید.');
} else if(!isAllowed) {
  reset();
  say('⛔ دسترسی شما به اطلاعات پروژه‌های سازمان فعال نشده است.\nشناسه کاربر: '+userId+'\nاز مدیر بخواهید شناسه شما را به فهرست مجاز اضافه کند.',kb([]));
} else if(incoming.callback==='m:main' || incoming.text==='/start' || incoming.text==='/menu' || incoming.text==='/cancel') {
  reset();say('به دستیار اطلاعات پروژه‌های سازمان خوش آمدید. گزینه موردنظر را انتخاب کنید.');
} else if(incoming.callback==='m:search') {
  step='search';draft={};ask('🔎 نام پروژه، گروه پروژه یا کد SAP را تایپ کنید.');
} else if(incoming.callback.startsWith('s:page:')) {
  if(!draft.query){step='search';ask('جستجوی قبلی منقضی شده است. نام پروژه یا کد را دوباره وارد کنید.');}
  else {const q=norm(draft.query);
    const matches=allProjects.filter(p=>[p.Project_Name,p.Project_Group,p.SAP_Code].some(v=>norm(v).includes(q)));
    const d=paged(matches,incoming.callback.split(':')[2],'s:page','🔎 نتایج جستجوی «'+draft.query+'»');step='search_results';say(d.text,d.keyboard);}
} else if(incoming.callback.startsWith('p:')) {
  reset();const p=findProject(incoming.callback.slice(2));
  if(p){const d=details(p);say(d.text,d.keyboard);} else say('پروژه پیدا نشد یا اطلاعات تغییر کرده است.');
} else if(incoming.callback.startsWith('m:list:')) {
  reset();const d=paged(allProjects.slice().sort((a,b)=>String(a.Project_Name).localeCompare(String(b.Project_Name),'fa')),incoming.callback.split(':')[2],'m:list','📋 فهرست پروژه‌ها');say(d.text,d.keyboard);
} else if(incoming.callback==='m:bom') {
  reset();say('وضعیت موردنظر را انتخاب کنید:',kb([
    [button('✅ BOM ثبت شده','m:filter:y:0')],
    [button('❌ BOM ثبت نشده','m:filter:n:0')],back()]));
} else if(incoming.callback.startsWith('m:filter:')) {
  reset();const a=incoming.callback.split(':');
  const selected=allProjects.filter(p=>p.BOM_Status===(a[2]==='y'?'registered':'not_registered'));
  const d=paged(selected,a[3],'m:filter:'+a[2],a[2]==='y'?'✅ دارای BOM':'❌ فاقد BOM');say(d.text,d.keyboard);
} else if(incoming.callback==='m:stats') {
  reset();const yes=allProjects.filter(p=>p.BOM_Status==='registered').length;
  const no=allProjects.filter(p=>p.BOM_Status==='not_registered').length;
  const unknown=allProjects.length-yes-no;
  say('📊 گزارش پروژه‌های سازمان\n'+
    'کل پروژه‌ها: '+allProjects.length+'\n'+
    '✅ BOM ثبت شده: '+yes+'\n'+
    '❌ BOM ثبت نشده: '+no+'\n'+
    '❔ نامشخص: '+unknown+'\n'+
    'درصد ثبت BOM: '+(allProjects.length?(100*yes/allProjects.length).toFixed(1):'0')+'٪',
    kb([[button('❌ پروژه‌های فاقد BOM','m:filter:n:0')],back()]));
} else if(incoming.callback.startsWith('m:users:')) {
  if(!isAdmin) say('⛔ فقط مدیر اجازه مشاهده کاربران را دارد.');
  else {reset();const d=userPaged(incoming.callback.split(':')[2]);say(d.text,d.keyboard);}
} else if(incoming.callback==='m:uadd') {
  if(!isAdmin) say('⛔ فقط مدیر اجازه افزودن کاربر دارد.');
  else {step='new_user_id';draft={};ask('شناسه عددی بله همکار جدید را وارد کنید.\nهمکار می‌تواند با دستور /id شناسه خودش را ببیند.');}
} else if(incoming.callback.startsWith('user:')) {
  if(!isAdmin) say('⛔ دسترسی ندارید.');
  else {reset();const u=findUser(incoming.callback.slice(5));if(!u)say('کاربر پیدا نشد.');else say(userDetails(u),userMenu(u));}
} else if(incoming.callback.startsWith('ur:')) {
  if(!isAdmin) say('⛔ دسترسی ندارید.');
  else {const a=incoming.callback.split(':');const u=findUser(a[2]);reset();
    if(!u)say('کاربر پیدا نشد.');
    else if(BOOTSTRAP_ADMIN_USER_IDS.includes(String(u.User_ID)) && a[1]==='v')say('نقش مدیر بازیابی را نمی‌توان از ربات حذف کرد.');
    else {userMutation={...u,Role:a[1]==='a'?'admin':'viewer',Updated_At:now,Updated_By:userId};auditChange('user_role',u.User_ID,u,userMutation);say('✅ نقش کاربر تغییر کرد.\n'+userDetails(userMutation),userMenu(userMutation));}}
} else if(incoming.callback.startsWith('ut:')) {
  if(!isAdmin) say('⛔ دسترسی ندارید.');
  else {const u=findUser(incoming.callback.slice(3));reset();
    if(!u)say('کاربر پیدا نشد.');
    else if(BOOTSTRAP_ADMIN_USER_IDS.includes(String(u.User_ID)))say('مدیر بازیابی را نمی‌توان غیرفعال کرد.');
    else {userMutation={...u,Active:String(u.Active).toLowerCase()==='true'?'false':'true',Updated_At:now,Updated_By:userId};auditChange('user_active',u.User_ID,u,userMutation);say('✅ وضعیت کاربر تغییر کرد.\n'+userDetails(userMutation),userMenu(userMutation));}}
} else if(incoming.callback.startsWith('nu:role:')) {
  if(!isAdmin||step!=='new_user_role')say('این مرحله معتبر نیست.');
  else {const role=incoming.callback.endsWith(':a')?'admin':'viewer';draft.Role=role;step='new_user_confirm';say('کاربر جدید:\n'+userDetails({...draft,Role:role,Active:'true'})+'\n\nثبت شود؟',kb([[button('✅ تأیید ثبت کاربر','nu:save')],back()]));}
} else if(incoming.callback==='nu:save') {
  if(!isAdmin||step!=='new_user_confirm'||!draft.User_ID||!draft.Display_Name||!draft.Role)say('این مرحله معتبر نیست.');
  else if(findUser(String(draft.User_ID))){reset();say('این شناسه قبلاً در فهرست کاربران وجود دارد.');}
  else {userMutation={User_ID:draft.User_ID,Display_Name:draft.Display_Name,Role:draft.Role,Active:'true',Updated_At:now,Updated_By:userId};
    auditChange('user_create',draft.User_ID,{},userMutation);reset();say('✅ همکار جدید ثبت شد.\n'+userDetails(userMutation));}
} else if(incoming.callback==='m:add') {
  if(!isAdmin) say('⛔ فقط مدیر اجازه ثبت پروژه دارد.');
  else {step='add_name';draft={};ask('➕ ثبت پروژه جدید\nمرحله ۱/۴: نام پروژه را وارد کنید.');}
} else if(incoming.callback.startsWith('m:manage:')) {
  if(!isAdmin) say('⛔ فقط مدیر اجازه مدیریت پروژه‌ها دارد.');
  else {reset();const d=paged(allProjects.slice().sort((a,b)=>String(a.Project_Name).localeCompare(String(b.Project_Name),'fa')),incoming.callback.split(':')[2],'m:manage','🛠 مدیریت پروژه‌ها');say(d.text,d.keyboard);}
} else if(incoming.callback.startsWith('e:')) {
  if(!isAdmin) say('⛔ دسترسی ندارید.');
  else {const p=findProject(incoming.callback.slice(2));reset();if(!p)say('پروژه پیدا نشد.');else say('ویرایش پروژه:\n'+projectText(p),kb([
    [button('✏️ نام','f:name:'+p.Project_ID),button('✏️ گروه','f:group:'+p.Project_ID)],
    [button('✏️ کد SAP','f:sap:'+p.Project_ID),button('🔄 وضعیت BOM','b:'+p.Project_ID)],back()]));}
} else if(incoming.callback.startsWith('f:')) {
  if(!isAdmin) say('⛔ دسترسی ندارید.');
  else {const a=incoming.callback.split(':');const p=findProject(a[2]);if(!p)say('پروژه پیدا نشد.');else{step='edit_'+a[1];draft={Project_ID:p.Project_ID};ask('مقدار جدید را برای '+({name:'نام پروژه',group:'گروه پروژه',sap:'کد SAP'}[a[1]]||'فیلد')+' وارد کنید.');}}
} else if(incoming.callback.startsWith('b:')) {
  if(!isAdmin) say('⛔ دسترسی ندارید.');
  else {const p=findProject(incoming.callback.slice(2));reset();if(!p)say('پروژه پیدا نشد.');else say(projectText(p)+'\n\nوضعیت جدید را انتخاب کنید:',kb([
    [button('✅ ثبت شده','u:y:'+p.Project_ID),button('❌ ثبت نشده','u:n:'+p.Project_ID)],back()]));}
} else if(incoming.callback.startsWith('u:')) {
  if(!isAdmin) say('⛔ دسترسی ندارید.');
  else {const a=incoming.callback.split(':');const p=findProject(a[2]);reset();if(!p)say('پروژه پیدا نشد.');else{
    mutation={...p,BOM_Status:a[1]==='y'?'registered':'not_registered',
      BOM_Updated_At:now,BOM_Updated_By:userId,Updated_At:now,Updated_By:userId};
    auditChange('bom_change',p.Project_Group,p,mutation);
    const d=details(mutation);say('✅ وضعیت BOM به‌روزرسانی شد.\n\n'+d.text,d.keyboard);
  }}
} else if(incoming.callback.startsWith('a:bom:')) {
  if(!isAdmin || step!=='add_bom') say('این مرحله منقضی شده است. ثبت را از ابتدا شروع کنید.');
  else {draft.BOM_Status=incoming.callback.endsWith(':y')?'registered':'not_registered';step='add_confirm';say('لطفاً اطلاعات را بررسی کنید:\n\n'+projectText({Project_Name:draft.Project_Name,Project_Group:draft.Project_Group,SAP_Code:draft.SAP_Code,BOM_Status:draft.BOM_Status})+'\n\nتأیید نهایی؟',kb([
    [button('✅ ذخیره پروژه','a:save')],
    [button('❌ لغو','m:main')]]));}
} else if(incoming.callback==='a:save') {
  if(!isAdmin || step!=='add_confirm' || !draft.Project_Name || !draft.Project_Group || !draft.SAP_Code || !draft.BOM_Status) say('ثبت معتبر نیست؛ از ابتدا شروع کنید.');
  else {const duplicate=allProjects.find(p=>norm(p.Project_Group)===norm(draft.Project_Group));
    if(duplicate){reset();const d=details(duplicate);say('⚠️ پروژه‌ای با همین گروه پروژه و کد SAP وجود دارد. ثبت تکراری انجام نشد.\n\n'+d.text,d.keyboard);}
    else {const id='P'+Date.now().toString(36)+Math.random().toString(36).slice(2,6);mutation={Project_ID:id,Project_Name:draft.Project_Name,Project_Group:draft.Project_Group,SAP_Code:String(draft.SAP_Code),BOM_Status:draft.BOM_Status,
      BOM_Updated_At:now,BOM_Updated_By:userId,Updated_At:now,Updated_By:userId};
      auditChange('project_create',mutation.Project_Group,{},mutation);reset();say('✅ پروژه ثبت شد.\n\n'+projectText(mutation));}
  }
} else if(incoming.callback) {
  say('دکمه نامعتبر یا قدیمی است. از منوی اصلی ادامه دهید.');
} else if(isAdmin && step==='new_user_id') {
  const val=norm(incoming.text);
  if(!/^\d{3,20}$/.test(val))ask('شناسه بله باید عددی باشد. دوباره وارد کنید.');
  else {draft.User_ID=val;step='new_user_name';ask('نام و نام خانوادگی همکار را وارد کنید.');}
} else if(isAdmin && step==='new_user_name') {
  const val=incoming.text.trim();
  if(val.length<2||val.length>80)ask('نام باید بین ۲ تا ۸۰ کاراکتر باشد. دوباره وارد کنید.');
  else {draft.Display_Name=val;step='new_user_role';say('سطح دسترسی همکار را انتخاب کنید:',kb([
    [button('👁 فقط مشاهده','nu:role:v'),button('👑 مدیر','nu:role:a')],back()]));}
} else if(isAdmin && step.startsWith('edit_')) {
  const p=findProject(String(draft.Project_ID||''));const field=step.slice(5);const val=incoming.text.trim();reset();
  if(!p) say('پروژه پیدا نشد.');
  else if(!val || val.length>120) say('مقدار نامعتبر است؛ باید ۱ تا ۱۲۰ کاراکتر باشد.');
  else if(field==='sap'&&!/^[0-9۰-۹٠-٩]+$/.test(val)) say('کد SAP باید عددی باشد.');
  else if(field==='group'&&allProjects.some(o=>String(o.Project_ID)!==String(p.Project_ID)&&norm(o.Project_Group)===norm(val)))say('این گروه پروژه قبلاً ثبت شده و نمی‌تواند تکراری باشد.');
  else {mutation={...p,Updated_At:now,Updated_By:userId};const map={name:'Project_Name',group:'Project_Group',sap:'SAP_Code'};mutation[map[field]]=val;
    auditChange('project_edit_'+field,p.Project_Group,p,mutation);const d=details(mutation);say('✅ اطلاعات ویرایش شد.\n\n'+d.text,d.keyboard);}
} else if(isAdmin && step.startsWith('add_') && incoming.text) {
  const val=incoming.text.trim();
  if(!val || val.length>120) ask('مقدار باید ۱ تا ۱۲۰ کاراکتر باشد. دوباره وارد کنید.');
  else if(step==='add_name'){draft.Project_Name=val;step='add_group';ask('مرحله ۲/۴: گروه پروژه را وارد کنید (مثلاً 912B-938).');}
  else if(step==='add_group'){draft.Project_Group=val;step='add_sap';ask('مرحله ۳/۴: کد محصول SAP را وارد کنید.');}
  else if(step==='add_sap'){
    if(!/^[0-9۰-۹٠-٩]+$/.test(val))ask('کد SAP باید فقط عدد باشد. دوباره وارد کنید.');
    else {draft.SAP_Code=val;step='add_bom';say('مرحله ۴/۴: آیا BOM ثبت شده است؟',kb([
      [button('✅ ثبت شده','a:bom:y'),button('❌ ثبت نشده','a:bom:n')],
      [button('❌ لغو','m:main')]]));}
  }
} else if(incoming.text) {
  const q=norm(incoming.text);
  const results=allProjects.filter(p=>[p.Project_Name,p.Project_Group,p.SAP_Code].some(v=>norm(v).includes(q)));
  step='search';draft={};
  if(!results.length) ask('🔍 پروژه‌ای با عبارت «'+incoming.text+'» پیدا نشد.\nعبارت دیگری بفرستید یا لغو کنید.');
  else if(results.length===1){const d=details(results[0]);say(d.text,d.keyboard);reset();}
  else {draft={query:incoming.text};step='search_results';const d=paged(results,0,'s:page','🔎 نتایج جستجوی «'+incoming.text+'»');say(d.text,d.keyboard);}
} else {
  say('به دستیار اطلاعات پروژه‌های سازمان خوش آمدید. گزینه موردنظر را انتخاب کنید.');
}

// Glass-button clicks update the same window (editMessageText); typed text gets a new window.
const editInPlace = !!(incoming.callback_id && incoming.message_id) && !fromFixedMenu;
const isNewUser = !allSessions.some(x=>String(x.User_ID)===userId);
const showFixedMenu = !readError && isAllowed && (incoming.text==='/start' || incoming.text==='/menu' || isNewUser);
const session = {
  User_ID:userId, Step:step, Draft_JSON:JSON.stringify(draft), Updated_At:now,
};
return [{json:{
  chat_id:chatId, user_id:userId, callback_id:incoming.callback_id,
  text, keyboard, session, mutation, userMutation, audit, readFailure:readError,
  method: editInPlace ? 'editMessageText' : 'sendMessage', message_id: incoming.message_id,
  showFixedMenu, fixedKeyboard: showFixedMenu ? fixedKeyboard() : null,
}}];
